 {page==='home'&&<><section className="hero-panel"><div className="hero-shade"/><div className="hero-content"><span className="eyebrow">O TEU TREINO. A TUA EVOLUÇÃO.</span><h1>Vamos treinar<span className="red">?</span></h1><p>Consistência hoje. Resultados ao longo do tempo.</p><div className="hero-stats"><div><small>PLANO ATUAL</small><b>{dashboardWorkout?.dia} · {dashboardWorkout?.nome}</b></div><div><small>ESTA SEMANA</small><b>{weekSessions} <small>sessões</small></b></div><div><small>ÚLTIMA SESSÃO</small><b>{lastTraining?.dia||'—'}</b></div><div><small>EXERCÍCIOS NO PLANO</small><b>{allExercises.length}</b></div></div><button className="primary-btn" onClick={startWorkout}><Play size={17} fill="currentColor"/> Começar treino <ArrowUpRight size={16}/></button></div></section><div className="section-head"><div><span className="eyebrow">RESUMO</span><h2>A tua semana</h2></div><button className="text-btn" onClick={()=>setPage('progress')}>Ver evolução <ArrowUpRight size={15}/></button></div><div className="metric-grid"><Metric icon={CalendarDays} label="Treinos esta semana" value={`${weekSessions}/5`} note="sessões concluídas"/><Metric icon={Dumbbell} label="Total de treinos" value={sessions.length} note="sessões registadas"/><Metric icon={Scale} label="Peso atual" value={latestWeight==='—'?'—':`${latestWeight} kg`} note="última avaliação"/><Metric icon={Trophy} label="Exercícios no plano" value={allExercises.length} note="em 6 dias"/></div><div className="home-lower"><section className="panel"><div className="panel-title"><h3>Evolução do peso</h3><button className="text-btn" onClick={()=>setPage('progress')}>Ver tudo</button></div><WeightChart data={chartData}/></section><section className="panel today-panel"><div className="panel-title"><h3>Próximo treino</h3><span className="tag">{dashboardWorkout?.dia}</span></div><h2>{dashboardWorkout?.nome}</h2><p>{plan.descricoes?.[nextDay]||'O próximo treino da tua sequência.'}</p><div className="today-meta"><span><Dumbbell size={15}/>{dashboardWorkout?.exercicios?.length||0} exercícios</span><span><Clock3 size={15}/>60–75 min</span></div><button className="outline-btn full" onClick={()=>{setDay(nextDay);setPage('workouts')}}>Ver treino <ArrowUpRight size={15}/></button></section></div><section className="portfolio-return-panel"><div><span className="eyebrow">OUTROS PROJETOS</span><h2>Voltar ao portefólio</h2><p>Explora os meus projetos, formação e percurso profissional.</p></div><a className="outline-btn" href="https://rlpimenta.github.io/Portfolio/" target="_blank" rel="noopener noreferrer">Abrir portefólio <ArrowUpRight size={15}/></a></section></>}
 {page==='workouts'&&<><div className="page-heading"><div><span className="eyebrow">O TEU PLANO</span><h1>Treinos</h1><p>Seleciona um dia e acompanha cada exercício.</p></div><button className="primary-btn small" onClick={()=>setModal('add')}><Plus size={16}/> Adicionar exercício</button></div><div className="workout-layout"><aside className="day-list"><h3>Os meus treinos</h3>{workouts.map(w=><button key={w.dia} className={`day-btn ${day===w.dia?'selected':''}`} onClick={()=>setDay(w.dia)}><b>{w.dia}</b><span>{w.nome}</span><small>{w.exercicios.length} exercícios</small></button>)}<div className="cardio-mini"><Flame size={17}/><div><b>Cardio</b><small>{plan.cardio?.[day]?.tipo||'Personalizado'}</small></div></div></aside><section className="workout-main"><div className="workout-title"><div><span className="eyebrow">TREINO SELECIONADO</span><h2>{day} — {current?.nome}</h2><p>{plan.descricoes?.[day]}</p></div><span className="tag">{exercises.length} exercícios · {exercises.filter(e=>e.opcional).length} opcionais</span></div><div className="progress-line"><span style={{width:`${exercises.length?completed/exercises.length*100:0}%`}}/></div><div className="progress-caption"><span>{completed} de {exercises.length} exercícios concluídos</span><b>{exercises.length?Math.round(completed/exercises.length*100):0}%</b></div><div className="workout-tools"><label className="searchbox"><Search size={17}/><input placeholder="Pesquisar exercício..." value={query} onChange={e=>setQuery(e.target.value)}/></label><select value={group} onChange={e=>setGroup(e.target.value)}><option>Todos</option>{allGroups.map(g=><option key={g}>{g}</option>)}</select></div><div className="exercise-grid">{exercises.filter(e=>(e.nome.toLowerCase().includes(query.toLowerCase()))&&(group==='Todos'||e.grupo===group)).sort((a,b)=>Number(isDone(a.id))-Number(isDone(b.id))).map((original,i)=>{const e=sessionReplacements[day+'-'+original.id]||original;return <ExerciseCard key={original.id} ex={e} original={original} index={i} done={isDone(original.id)} weight={weightValue(weights[e.recordId||original.id])||original.peso||''} setLog={setSetLogs} logs={setLogs} onDone={()=>toggleDone(original)} onEdit={()=>setEdit(original)} onDelete={()=>deleteExercise(original.id)} onWeight={v=>saveWeight(e.recordId||original.id,v)} onTimer={()=>{setTimer(90);setTimerOn(true);setModal('timer')}} onImageClick={()=>{setReplacementTarget(original);setModal('alternatives')}} onReorder={reorderExercises} onReplace={alt=>{setSessionReplacements(prev=>({...prev,[day+'-'+original.id]:{...alt,id:original.id,substitui:original.nome}}));setModal('');showToast('Alternativa aplicada apenas nesta sessão')}} onRestore={()=>{setSessionReplacements(prev=>{const n={...prev};delete n[day+'-'+original.id];return n});showToast('Exercício original restaurado')}}/>})}</div>{!exercises.length&&<div className="empty">Ainda não existem exercícios neste treino.</div>}<div className="finish-row"><button className="outline-btn" onClick={()=>setModal('add')}><Plus size={16}/> Adicionar exercício</button><button className="primary-btn" onClick={finishWorkout}><Check size={16}/> Terminar e guardar treino</button></div></section></div></>}
 {page==='progress'&&<ProgressPage assess={assess} setAssess={setAssess} chartData={chartData} latestWeight={latestWeight} previous={previous} last={lastAssessment} sessions={sessions}/>}
